<?php
namespace App\Core;
final class MaintenancePage
{
    public static function render(): void { $e=ConsoleView::escape(...); $message=Settings::get('maintenance_message','Estamos realizando mejoras. Volveremos pronto.'); $image=Settings::get('maintenance_image'); if (!preg_match('~^/(?:assets/site-icons/[a-f0-9]{32}\.png|uploads/maint_[a-f0-9]+\.(?:png|jpe?g|webp))$~D',$image)) $image=''; $title=Settings::get('site_title','GoldenSiteCMS'); ?><!doctype html><html lang="<?= $e(Locale::language()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title><?= $e($title) ?> · Mantenimiento</title><?= ThemeService::head().Typography::style().SiteIcon::head() ?><style>body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box}.nx-maintenance-card{width:100%;max-width:800px;background:var(--card-bg);border:1px solid var(--primary);border-radius:24px;padding:clamp(26px,6vw,70px);box-sizing:border-box}.nx-maintenance-card img{width:80px;height:80px;object-fit:contain;border-radius:12px}.nx-maintenance-card h1{line-height:1.15}.nx-maintenance-card p{opacity:.8;line-height:1.8}.nx-maintenance-label{font:11px Consolas;letter-spacing:3px;color:var(--primary)}</style></head><body class="nx-public"><main class="nx-maintenance-card"><?php if ($image): ?><img src="<?= $e($image) ?>" alt="<?= $e($title) ?>"><?php else: ?><?= GoldensiteIcon::svg('maintenance-mode',52) ?><?php endif ?><p class="nx-maintenance-label"><?= $e($title) ?> / MANTENIMIENTO</p><h1>Estamos preparando lo que sigue.</h1><p><?= $e($message) ?></p><p class="nx-maintenance-label">Volveremos pronto.</p><a href="/login" style="color:var(--primary)">Acceso administrativo</a></main></body></html><?php }
}
